            () -> ReindexTaskLookup.validateProbeResult(
                taskId,
                new TaskResult(false, ReindexManagementTestUtils.taskInfo(taskId, "other_action".equals("other_action") ? "reindex" : "reindex", parentTaskId))
            )
        );

        assertEquals(ReindexTaskLookup.notFoundException(taskId).getMessage(), e.getMessage());
    }
