 68	    public void testCancelTaskRequestIsScopedToReindexParentTasks() {
 69	        mockCancelTasks(new ListTasksResponse(List.of(ReindexManagementTestUtils.reindexTaskInfo(taskId)), List.of(), List.of()));
 70	
 71	        safeAwait((ActionListener<CancelReindexResponse> l) -> action.doExecute(mock(), new CancelReindexRequest(taskId, false), l));
 72	
 73	        ArgumentCaptor<CancelTasksRequest> captor = ArgumentCaptor.captor();
 74	        verify(client).execute(eq(TransportCancelTasksAction.TYPE), captor.capture(), any());
 75	        CancelTasksRequest sent = captor.getValue();
 76	        assertThat(sent.getTargetTaskId(), is(taskId));
 77	        assertThat(sent.getActions(), is(new String[] { ReindexAction.NAME }));
 78	        assertThat("exclude_child_tasks is what protects us from sub-task cancellation", sent.excludeChildTasks(), is(true));
 79	        assertThat("waitForCompletion is handled separately via Get Reindex", sent.waitForCompletion(), is(false));
 80	    }
