 72	    public void testRelocatedTaskRewritten() {
 73	        final TaskId originalId = new TaskId("originalNode", randomNonNegativeLong());
 74	        final TaskId relocatedId = new TaskId("relocatedNode", randomNonNegativeLong());
 75	        final long originalStartMillis = randomLongBetween(0, 100);
 76	        final long relocatedStartMillis = randomLongBetween(originalStartMillis, originalStartMillis + randomLongBetween(0, 100));
 77	        final long relocatedRunningNanos = randomNonNegativeLong();
 78	        final TaskInfo info = ReindexManagementTestUtils.relocatedReindexTaskInfo(
 79	            relocatedId,
 80	            originalId,
 81	            relocatedStartMillis,
 82	            relocatedRunningNanos,
 83	            randomBoolean(),
 84	            randomBoolean(),
 85	            originalStartMillis
 86	        );
 87	
 88	        returnGivenTasksOnActionExecution(List.of(info));
 89	        action.doExecute(mock(), new ListReindexRequest(randomBoolean()), listener);
 90	
 91	        assertNull(failureRef.get());
 92	        assertThat(responseRef.get().getTasks(), hasSize(1));
 93	        final TaskInfo rewritten = responseRef.get().getTasks().getFirst();
 94	        assertThat(rewritten.taskId(), equalTo(originalId));
 95	        assertThat(rewritten.taskId(), equalTo(rewritten.originalTaskId()));
 96	        assertThat(rewritten.node(), equalTo(originalId.getNodeId()));
 97	        assertThat(rewritten.startTime(), equalTo(originalStartMillis));
 98	        assertThat(rewritten.startTime(), equalTo(rewritten.originalStartTimeMillis()));
 99	        long expectedRunningNanos = relocatedRunningNanos + TimeUnit.MILLISECONDS.toNanos(relocatedStartMillis - originalStartMillis);
100	        assertThat(rewritten.runningTimeNanos(), equalTo(expectedRunningNanos));
101	    }
